import { Router } from 'express';
import { requireRole } from '../middleware/session.js';

/** Lecture ids are generated by the app: base-36 time plus a random suffix. */
const LECTURE_ID = /^[a-z0-9]{1,40}$/;
const MAX_LECTURES_PER_USER = 2000;

/**
 * Cloud backup of a professor's lectures: transcript, quiz and practice attempts (not
 * the audio, which is only needed until it has been transcribed).
 *
 * The app owns the lecture format; the server stores each one as an opaque JSON document,
 * visible only to its owner. The app pushes a lecture whenever it changes and pulls the
 * list after sign-in, restoring any lecture that is missing from the device.
 */
export function lecturesRouter({ db }) {
  const router = Router();
  router.use(requireRole('professor'));

  const rowId = (userId, lectureId) => `${userId}_${lectureId}`;

  /** GET /v1/lectures */
  router.get('/', (req, res) => {
    const rows = db.data.lectures.filter((r) => r.ownerId === req.user.id);
    res.json({ lectures: rows.map((r) => r.data) });
  });

  /** PUT /v1/lectures/:lectureId { lecture } */
  router.put('/:lectureId', (req, res) => {
    const { lectureId } = req.params;
    const data = req.body?.lecture;
    if (!LECTURE_ID.test(lectureId)) return res.status(400).json({ error: 'Invalid lecture id' });
    if (!data || typeof data !== 'object' || Array.isArray(data) || data.id !== lectureId) {
      return res.status(400).json({ error: 'Invalid lecture' });
    }

    const id = rowId(req.user.id, lectureId);
    const exists = db.data.lectures.some((r) => r.id === id);
    if (!exists && db.data.lectures.filter((r) => r.ownerId === req.user.id).length >= MAX_LECTURES_PER_USER) {
      return res.status(409).json({ error: 'Lecture backup is full. Delete some old lectures first.', code: 'lecture_limit' });
    }

    const row = { id, ownerId: req.user.id, lectureId, data, updatedAt: new Date().toISOString() };
    db.data.lectures = [...db.data.lectures.filter((r) => r.id !== id), row];
    db.save();
    res.json({ ok: true, updatedAt: row.updatedAt });
  });

  /** DELETE /v1/lectures/:lectureId: idempotent, so a retried delete never fails. */
  router.delete('/:lectureId', (req, res) => {
    const id = rowId(req.user.id, req.params.lectureId);
    const before = db.data.lectures.length;
    db.data.lectures = db.data.lectures.filter((r) => r.id !== id);
    if (db.data.lectures.length !== before) db.save();
    res.json({ ok: true });
  });

  return router;
}
